import {createHash} from "node:crypto";
import {readFile, readdir, mkdir, writeFile} from "node:fs/promises";
import {fileURLToPath} from "node:url";
import path from "node:path";

const repositoryRoot = path.resolve(path.dirname(fileURLToPath(import.meta.url)), "..");
const contractsRoot = path.join(repositoryRoot, "Contracts");
const generatedPath = path.join(
  repositoryRoot,
  "packages",
  "authoring-sdk",
  "src",
  "generated",
  "contracts.ts",
);
const lockPath = path.join(contractsRoot, "contracts.lock.json");
const checkOnly = process.argv.includes("--check");

function sortValue(value) {
  if (Array.isArray(value)) return value.map(sortValue);
  if (value !== null && typeof value === "object") {
    return Object.fromEntries(
      Object.keys(value)
        .sort((left, right) => left.localeCompare(right, "en"))
        .map((key) => [key, sortValue(value[key])]),
    );
  }
  return value;
}

function canonicalJson(value) {
  return JSON.stringify(sortValue(value));
}

function sha256(value) {
  return createHash("sha256").update(value, "utf8").digest("hex");
}

function normalizeLineEndings(value) {
  return value.replace(/\r\n/g, "\n");
}

async function readJson(filePath) {
  const text = await readFile(filePath, "utf8");
  if (text.startsWith("\uFEFF")) throw new Error(`${filePath} must not contain a UTF-8 BOM`);
  return JSON.parse(text);
}

const manifest = await readJson(path.join(contractsRoot, "contract-manifest.json"));
if (
  manifest.format !== "PrismatiXContractManifest" ||
  manifest.schemaRevision !== 1 ||
  !Array.isArray(manifest.contracts)
) {
  throw new Error("Contracts/contract-manifest.json has an unsupported shape");
}

const schemaNames = (await readdir(contractsRoot))
  .filter((name) => name.endsWith(".schema.json"))
  .sort((left, right) => left.localeCompare(right, "en"));
const schemas = {};
const hashes = {};
for (const name of schemaNames) {
  const schema = await readJson(path.join(contractsRoot, name));
  if (schema.$schema !== "https://json-schema.org/draft/2020-12/schema" ||
      typeof schema.$id !== "string") {
    throw new Error(`${name} must declare JSON Schema 2020-12 and a stable $id`);
  }
  schemas[name] = schema;
  hashes[name] = sha256(canonicalJson(schema));
}
for (const contract of manifest.contracts) {
  if (!schemas[contract.schema]) {
    throw new Error(`Contract ${contract.id} references missing schema ${contract.schema}`);
  }
}

const lock = sortValue({
  format: "PrismatiXContractLock",
  schemaRevision: 1,
  manifestSha256: sha256(canonicalJson(manifest)),
  schemas: hashes,
});
const lockText = `${JSON.stringify(lock, null, 2)}\n`;
const generatedText = `// Generated by scripts/generate-contract-bundle.mjs. Do not edit.\n` +
  `export const contractManifest: Readonly<Record<string, unknown>> = ${JSON.stringify(sortValue(manifest), null, 2)};\n\n` +
  `export const contractSchemas: Readonly<Record<string, object>> = ${JSON.stringify(sortValue(schemas), null, 2)};\n\n` +
  `export const contractHashes: Readonly<Record<string, string>> = ${JSON.stringify(sortValue(hashes), null, 2)};\n`;

if (checkOnly) {
  const [currentLock, currentGenerated] = await Promise.all([
    readFile(lockPath, "utf8").catch(() => ""),
    readFile(generatedPath, "utf8").catch(() => ""),
  ]);
  if (
    normalizeLineEndings(currentLock) !== lockText ||
    normalizeLineEndings(currentGenerated) !== generatedText
  ) {
    throw new Error("Generated contract bundle is stale; run npm run contracts:generate");
  }
} else {
  await mkdir(path.dirname(generatedPath), {recursive: true});
  await Promise.all([
    writeFile(lockPath, lockText, "utf8"),
    writeFile(generatedPath, generatedText, "utf8"),
  ]);
}
